/**
 * The closed capability-scoped surface: every selected official operation,
 * the vendor namespace, and nothing else.
 */
export interface OpenComputeSurface {
  readonly accounts: OpenComputeAccountsNode;
  readonly aiSearch: OpenComputeAiSearchNode;
  readonly d1: OpenComputeD1Node;
  readonly kv: OpenComputeKvNode;
  readonly memberships: OpenComputeMembershipsNode;
  readonly queues: OpenComputeQueuesNode;
  readonly r2: OpenComputeR2Node;
  readonly user: OpenComputeUserNode;
  readonly vectorize: OpenComputeVectorizeNode;
  readonly workers: OpenComputeWorkersNode;
  readonly workflows: OpenComputeWorkflowsNode;
  readonly artifacts: Artifacts;
  readonly openCompute: OpenComputeVendorNode;
}

